INSERT INTO `algorithms` VALUES ('0dfaa799-e15c-4e7f-9c5e-a2711c59b877', '决策树分类', '通过树状结构对数据进行分类，易于理解和解释', 'llm', 'classification', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"algorithm\", \"label\": \"决策树\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {}, \"type\": \"output\", \"label\": \"分类结果\", \"position\": {\"x\": 100, \"y\": 250}}]}', '你是一个分类算法专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用决策树算法进行分类，并解释分类路径。', '<div class=\"algorithm-demo\">\n      <h3>决策树分类演示</h3>\n      <p>通过树状结构进行分类决策</p>\n    </div>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:05', '2025-12-25 20:19:05', NULL, NULL, NULL, 0, '2d', NULL);
INSERT INTO `algorithms` VALUES ('18ac0202-2caa-48e7-ab93-c2ca735827ae', '逻辑回归分类', '用于二分类问题，通过估计事件发生的概率进行分类', 'llm', 'classification', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}, {\"id\": \"e3\", \"source\": \"3\", \"target\": \"4\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"process\", \"label\": \"特征提取\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {}, \"type\": \"algorithm\", \"label\": \"逻辑回归\", \"position\": {\"x\": 100, \"y\": 250}}, {\"id\": \"4\", \"data\": {}, \"type\": \"output\", \"label\": \"分类结果\", \"position\": {\"x\": 100, \"y\": 350}}]}', '你是一个分类算法专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用逻辑回归算法进行分类，并给出分类结果和概率。', '<div class=\"algorithm-demo\">\n      <h3>逻辑回归分类演示</h3>\n      <div class=\"input-section\">\n        <label>输入特征：</label>\n        <input type=\"text\" id=\"class-input\" placeholder=\"输入特征值\" />\n        <button onclick=\"classify()\">分类</button>\n      </div>\n      <div class=\"result-section\">\n        <h4>分类结果：</h4>\n        <div id=\"classification-result\">等待输入...</div>\n      </div>\n    </div>\n    <script>\n      function classify() {\n        const input = document.getElementById(\'class-input\').value;\n        const probability = Math.random() * 0.3 + 0.7; // 示例概率\n        const result = probability > 0.8 ? \'类别A\' : \'类别B\';\n        document.getElementById(\'classification-result\').innerHTML = \n          `分类：${result}<br>概率：${(probability * 100).toFixed(2)}%`;\n      }\n    </script>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:04', '2025-12-25 20:19:04', NULL, NULL, NULL, 0, '2d', NULL);
INSERT INTO `algorithms` VALUES ('256f944d-32f8-481f-934a-b807a5a7faac', '层次聚类', '通过构建树状结构来表示数据的聚类关系，适用于探索数据的层次结构', 'llm', 'clustering', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"algorithm\", \"label\": \"层次聚类\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {}, \"type\": \"output\", \"label\": \"聚类树\", \"position\": {\"x\": 100, \"y\": 250}}]}', '你是一个聚类算法专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用层次聚类算法进行聚类分析，并展示聚类树状结构。', '<div class=\"algorithm-demo\">\n      <h3>层次聚类演示</h3>\n      <p>构建树状聚类结构</p>\n    </div>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:05', '2025-12-25 20:19:05', NULL, NULL, NULL, 0, '2d', NULL);
INSERT INTO `algorithms` VALUES ('4ed47ae4-dd9f-4cc5-88df-e1a9ebc445c5', '关联规则分析', '用于发现数据集中变量之间的关联关系，如市场篮分析中的\"啤酒与尿布\"现象', 'llm', 'attribution', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"algorithm\", \"label\": \"关联规则\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {}, \"type\": \"output\", \"label\": \"关联规则\", \"position\": {\"x\": 100, \"y\": 250}}]}', '你是一个归因分析专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用关联规则分析算法发现数据中的关联关系，并给出关联规则和置信度。', '<div class=\"algorithm-demo\">\n      <h3>关联规则分析演示</h3>\n      <div class=\"result-section\">\n        <h4>发现的关联规则：</h4>\n        <div id=\"rules-result\">\n          <p>规则1：A → B (支持度：30%, 置信度：75%)</p>\n          <p>规则2：C → D (支持度：25%, 置信度：80%)</p>\n        </div>\n      </div>\n    </div>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:05', '2025-12-25 20:19:05', NULL, NULL, NULL, 0, '2d', NULL);
INSERT INTO `algorithms` VALUES ('902d6967-addc-48f4-953d-c33c4fb934e1', 'K均值聚类', '将数据分为K个簇，使簇内数据点的相似度最大化', 'llm', 'clustering', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}, {\"id\": \"e3\", \"source\": \"3\", \"target\": \"4\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"process\", \"label\": \"数据标准化\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {\"k\": 3}, \"type\": \"algorithm\", \"label\": \"K均值聚类\", \"position\": {\"x\": 100, \"y\": 250}}, {\"id\": \"4\", \"data\": {}, \"type\": \"output\", \"label\": \"聚类结果\", \"position\": {\"x\": 100, \"y\": 350}}]}', '你是一个聚类算法专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用K均值聚类算法进行数据聚类分析，并给出聚类结果和簇中心。', '<div class=\"algorithm-demo\">\n      <h3>K均值聚类演示</h3>\n      <div class=\"input-section\">\n        <label>聚类数量K：</label>\n        <input type=\"number\" id=\"k-input\" value=\"3\" min=\"2\" max=\"10\" />\n        <button onclick=\"cluster()\">聚类</button>\n      </div>\n      <div class=\"result-section\">\n        <h4>聚类结果：</h4>\n        <div id=\"clustering-result\">等待输入...</div>\n      </div>\n    </div>\n    <script>\n      function cluster() {\n        const k = parseInt(document.getElementById(\'k-input\').value);\n        document.getElementById(\'clustering-result\').innerHTML = \n          `已分为 ${k} 个簇<br>簇内相似度：85%<br>簇间距离：较大`;\n      }\n    </script>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:05', '2025-12-25 20:19:05', NULL, NULL, NULL, 0, '2d', NULL);
INSERT INTO `algorithms` VALUES ('algo_1769243375260', 'jjj', '', 'llm', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, '2026-01-24 16:29:34', '2026-01-25 12:21:55', 'custom', '8', 'workflow_1769243375260', 0, '2d', '{\"nodes\": [{\"x\": 99, \"y\": 127, \"id\": \"node_1\", \"data\": {}, \"type\": \"input-text\", \"config\": {\"placeholder\": \"请输入...\", \"defaultValue\": \"\"}}, {\"x\": 442, \"y\": 112, \"id\": \"node_2\", \"data\": {}, \"type\": \"llm-deepseek\", \"config\": {\"model\": \"deepseek-v3\", \"maxTokens\": 4000, \"temperature\": 0.7, \"systemPrompt\": \"你是一个有帮助的AI助手。\"}}, {\"x\": 884.0989514699669, \"y\": 162.9795448319771, \"id\": \"node_3\", \"data\": {}, \"type\": \"output-text\", \"config\": {}}], \"metadata\": {\"name\": \"jjj\", \"version\": \"1.0.0\", \"createdAt\": \"2026-01-25T04:21:55.183Z\", \"algorithmId\": \"algo_1769243375260\"}, \"connections\": [{\"id\": \"conn_1769243448577\", \"to\": \"node_2\", \"from\": \"node_1\"}, {\"id\": \"conn_1769314889860\", \"to\": \"node_3\", \"from\": \"node_2\"}]}');
