INSERT INTO `algorithms` VALUES ('b9838551-9443-4d06-ad43-db032587336d', '支持向量机分类', '寻找最佳超平面以区分不同类别，适用于高维数据的分类', 'llm', 'classification', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"algorithm\", \"label\": \"SVM分类\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {}, \"type\": \"output\", \"label\": \"分类结果\", \"position\": {\"x\": 100, \"y\": 250}}]}', '你是一个分类算法专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用支持向量机(SVM)算法进行分类。', '<div class=\"algorithm-demo\">\n      <h3>支持向量机分类演示</h3>\n      <p>适用于高维数据的分类</p>\n    </div>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:05', '2025-12-25 20:19:05', NULL, NULL, NULL, 0, '2d', NULL);
INSERT INTO `algorithms` VALUES ('c1837e83-358f-49b9-b665-3329b2d04f3e', '支持向量回归', '基于支持向量机的回归方法，适用于非线性数据的预测', 'llm', 'prediction', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}, {\"id\": \"e3\", \"source\": \"3\", \"target\": \"4\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"process\", \"label\": \"特征工程\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {\"kernel\": \"rbf\"}, \"type\": \"algorithm\", \"label\": \"SVR回归\", \"position\": {\"x\": 100, \"y\": 250}}, {\"id\": \"4\", \"data\": {}, \"type\": \"output\", \"label\": \"预测结果\", \"position\": {\"x\": 100, \"y\": 350}}]}', '你是一个数据分析专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用支持向量回归(SVR)算法进行非线性预测分析。', '<div class=\"algorithm-demo\">\n      <h3>支持向量回归演示</h3>\n      <p>适用于非线性数据的预测分析</p>\n    </div>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:04', '2025-12-25 20:19:04', NULL, NULL, NULL, 0, '2d', NULL);
