INSERT INTO `algorithms` VALUES ('d72b7ebf-fd20-4d36-be1e-152fff42ff31', '线性回归预测', '用于建模因变量与一个或多个自变量之间的线性关系，常用于连续值的预测，如房价或股票价格', 'llm', 'prediction', '{\"edges\": [{\"id\": \"e1\", \"source\": \"1\", \"target\": \"2\"}, {\"id\": \"e2\", \"source\": \"2\", \"target\": \"3\"}, {\"id\": \"e3\", \"source\": \"3\", \"target\": \"4\"}], \"nodes\": [{\"id\": \"1\", \"data\": {}, \"type\": \"input\", \"label\": \"输入数据\", \"position\": {\"x\": 100, \"y\": 50}}, {\"id\": \"2\", \"data\": {}, \"type\": \"process\", \"label\": \"数据预处理\", \"position\": {\"x\": 100, \"y\": 150}}, {\"id\": \"3\", \"data\": {\"method\": \"linear\"}, \"type\": \"algorithm\", \"label\": \"线性回归\", \"position\": {\"x\": 100, \"y\": 250}}, {\"id\": \"4\", \"data\": {}, \"type\": \"output\", \"label\": \"预测结果\", \"position\": {\"x\": 100, \"y\": 350}}]}', '你是一个数据分析专家。根据以下上下文信息：{context}\n\n输入数据：{input}\n\n请使用线性回归算法进行预测分析，并给出预测结果和置信度。', '<div class=\"algorithm-demo\">\n      <h3>线性回归预测演示</h3>\n      <div class=\"input-section\">\n        <label>输入特征值：</label>\n        <input type=\"number\" id=\"feature-input\" placeholder=\"输入特征值\" />\n        <button onclick=\"predict()\">预测</button>\n      </div>\n      <div class=\"result-section\">\n        <h4>预测结果：</h4>\n        <div id=\"prediction-result\">等待输入...</div>\n      </div>\n    </div>\n    <script>\n      function predict() {\n        const input = document.getElementById(\'feature-input\').value;\n        const result = parseFloat(input) * 2.5 + 10; // 示例：y = 2.5x + 10\n        document.getElementById(\'prediction-result\').innerHTML = \n          `预测值：${result.toFixed(2)}<br>置信度：85%`;\n      }\n    </script>', NULL, NULL, NULL, NULL, 1, 1, '2025-12-25 20:19:04', '2025-12-25 20:19:04', NULL, NULL, NULL, 0, '2d', NULL);
