INSERT INTO `chat_flow` VALUES ('c8fe607b-5983-4175-b599-9b3bf9475709', '222', '{\"nodes\":[{\"id\":\"startAgentflow_0\",\"type\":\"agentFlow\",\"position\":{\"x\":-530.6958984546893,\"y\":18.16824734060077},\"width\":102,\"height\":65,\"selected\":false,\"positionAbsolute\":{\"x\":-530.6958984546893,\"y\":18.16824734060077},\"data\":{\"label\":\"Start\",\"name\":\"startAgentflow\",\"version\":1.1,\"type\":\"Start\",\"category\":\"Agent Flows\",\"description\":\"Starting point of the agentflow\",\"baseClasses\":[\"Start\"],\"color\":\"#7EE787\",\"hideInput\":true,\"inputs\":{\"startInputType\":\"chatInput\",\"formTitle\":\"\",\"formDescription\":\"\",\"formInputTypes\":\"\",\"startEphemeralMemory\":\"\",\"startState\":\"\",\"startPersistState\":\"\"},\"filePath\":\"E:\\\\ai-tools-100\\\\flow-demo\\\\Flowise\\\\packages\\\\server\\\\node_modules\\\\flowise-components\\\\dist\\\\nodes\\\\agentflow\\\\Start\\\\Start.js\",\"inputAnchors\":[],\"inputParams\":[{\"label\":\"Input Type\",\"name\":\"startInputType\",\"type\":\"options\",\"options\":[{\"label\":\"Chat Input\",\"name\":\"chatInput\",\"description\":\"Start the conversation with chat input\"},{\"label\":\"Form Input\",\"name\":\"formInput\",\"description\":\"Start the workflow with form inputs\"}],\"default\":\"chatInput\",\"id\":\"startAgentflow_0-input-startInputType-options\",\"display\":true},{\"label\":\"Form Title\",\"name\":\"formTitle\",\"type\":\"string\",\"placeholder\":\"Please Fill Out The Form\",\"show\":{\"startInputType\":\"formInput\"},\"id\":\"startAgentflow_0-input-formTitle-string\",\"display\":false},{\"label\":\"Form Description\",\"name\":\"formDescription\",\"type\":\"string\",\"placeholder\":\"Complete all fields below to continue\",\"show\":{\"startInputType\":\"formInput\"},\"id\":\"startAgentflow_0-input-formDescription-string\",\"display\":false},{\"label\":\"Form Input Types\",\"name\":\"formInputTypes\",\"description\":\"Specify the type of form input\",\"type\":\"array\",\"show\":