INSERT INTO `chat_messages` VALUES ('5e797d2e-396a-4876-9511-6df5e6efed72', 'daf8b87a-2299-4588-87d7-1b21e1e47852', 'assistant', '<think>**Analyzing the Inquiry\'s Intent**\n**Processing the User\'s Input**\n</think>\n我是极康AI智能体，一个大型语言模型，由 Google 训练。', '', NULL, '2025-12-24 16:43:23');
