INSERT INTO `chat_messages` VALUES ('msg_1765669335758_bcfcab51', 'session_1765644883243_9aflukk64', 'assistant', '我是一个由 OpenAI 训练的人工智能语言模型，名字叫 ChatGPT，基于 GPT-4 架构。可以帮你回答问题、写作与编辑、翻译、编程、学习辅导等。没有真正的情感或意识，只是根据大量文本数据来生成回应。\n\n你现在想做什么？告诉我你的需求，我可以直接帮你解答、给出建议或完成一个任务。', NULL, 163, '2025-12-14 07:42:16');
