INSERT INTO `generated_questions` VALUES ('29bf2f8c-a95f-4b73-8809-5a4fc70874d1', '6e904abd-1080-4504-82aa-002f9199e8e5', '{\"imageUrl\": null, \"questions\": [{\"id\": \"q1\", \"type\": \"_rawValue\", \"topic\": \"Python基础\", \"options\": [\"def\", \"function\", \"define\", \"func\"], \"question\": \"在Python中，用于定义函数的关键字是？\", \"difficulty\": \"easy\", \"explanation\": \"在Python编程语言中，使用\'def\'关键字来定义一个函数。\", \"correctAnswer\": \"def\"}, {\"id\": \"q2\", \"type\": \"_rawValue\", \"topic\": \"JavaScript基础\", \"options\": [\"string\", \"number\", \"boolean\", \"array\"], \"question\": \"下列哪个选项不是JavaScript中的原始数据类型？\", \"difficulty\": \"medium\", \"explanation\": \"数组（Array）属于对象类型，并非原始数据类型。JavaScript中的原始数据类型包括字符串（string）、数字（number）和布尔值（boolean）等。\", \"correctAnswer\": \"array\"}, {\"id\": \"q3\", \"type\": \"_rawValue\", \"topic\": \"Web开发基础\", \"options\": [\"<html>\", \"<body>\", \"<head>\", \"<title>\"], \"question\": \"HTML文档的结构标签是什么？\", \"difficulty\": \"easy\", \"explanation\": \"<html> 标签代表整个HTML文档的根元素。它包含了<head>和<body>两个主要部分。\", \"correctAnswer\": \"<html>\"}, {\"id\": \"q4\", \"type\": \"_rawValue\", \"topic\": \"CSS基础\", \"options\": [\"color\", \"background-color\", \"bgcolor\", \"bg-color\"], \"question\": \"CSS中设置元素背景颜色的属性是？\", \"difficulty\": \"easy\", \"explanation\": \"在CSS中，\'background-color\'属性用来设置元素的背景颜色。\", \"correctAnswer\": \"background-color\"}, {\"id\": \"q5\", \"type\": \"_rawValue\", \"topic\": \"React框架\", \"options\": [\"componentDidMount\", \"componentWillUnmount\", \"shouldComponentUpdate\", \"componentDidUpdate\"], \"question\": \"React组件生命周期方法中，哪个是在组件接收到新的props时被调用？\", \"difficulty\": \"medium\", \"explanation\": \"当React组件更新后，即完成了重新渲染，会调用\'componentDidUpdate\'方法。\", \"correctAnswer\": \"componentDidUpdate\"}, {\"id\": \"q6\", \"type\": \"_rawValue\", \"topic\": \"网络协议\", \"options\": [\"请求成功\", \"服务器错误\", \"未找到资源\", \"请求被接受但未处理\"], \"question\": \"HTTP状态码200表示什么？\", \"difficulty\": \"easy\", \"explanation\": \"HTTP状态码200 OK意味着客户端发送的请求已被服务器成功接收、理解并处理。\", \"correctAnswer\": \"请求成功\"}, {\"id\": \"q7\", \"type\": \"_rawValue\", \"topic\": \"版本控制系统\", \"options\": [\"pull\", \"fetch\", \"merge\", \"push\"], \"question\": \"在Git中，哪一个命令用于从远程仓库获取最新更改到本地而不自动合并？\", \"difficulty\": \"medium\", \"explanation\": \"\'git fetch\'允许你从远程存储库下载最新的更改到你的本地存储库，但不会自动将这些更改合并到你的工作分支。\", \"correctAnswer\": \"fetch\"}, {\"id\": \"q8\", \"type\": \"_rawValue\", \"topic\": \"数据库查询\", \"options\": [\"ORDER BY\", \"ASC\", \"DESC\", \"SORT\"], \"question\": \"SQL查询语句中，用于指定查询结果排序方向的关键字是？\", \"difficulty\": \"easy\", \"explanation\": \"在SQL中，\'ASC\'关键字用于指定结果集按照升序排列；相对地，\'DESC\'则用于降序排列。\", \"correctAnswer\": \"ASC\"}, {\"id\": \"q9\", \"type\": \"_rawValue\", \"topic\": \"JavaScript高级\", \"options\": [\"new Object()\", \"{}\", \"Object.create()\", \"以上都是\"], \"question\": \"以下哪种方式可以创建JavaScript对象？\", \"difficulty\": \"medium\", \"explanation\": \"在JavaScript中，可以通过多种方式创建对象，包括使用对象字面量({})、构造函数(new Object())以及Object.create()方法。\", \"correctAnswer\": \"以上都是\"}, {\"id\": \"q10\", \"type\": \"_rawValue\", \"topic\": \"Node.js基础\", \"options\": [\"http\", \"fs\", \"path\", \"os\"], \"question\": \"在Node.js中，哪个模块用于处理文件系统操作？\", \"difficulty\": \"easy\", \"explanation\": \"Node.js中的\'fs\'模块提供了与文件系统交互的功能，如读写文件等。\", \"correctAnswer\": \"fs\"}, {\"id\": \"q11\", \"type\": \"_rawValue\", \"topic\": \"Vue.js框架\", \"options\": [\"input\", \"div\", \"span\", \"p\"], \"question\": \"在Vue.js中，v-model指令主要用于实现双向数据绑定于哪种表单控件上？\", \"difficulty\": \"medium\", \"explanation\": \"v-model是Vue.js提供的一个特殊指令，常用于表单输入元素如<input>上以实现双向数据绑定。\", \"correctAnswer\": \"input\"}, {\"id\": \"q12\", \"type\": \"_rawValue\", \"topic\": \"API设计原则\", \"options\": [\"POST\", \"GET\", \"PUT\", \"DELETE\"], \"question\": \"RESTful API设计中，哪个HTTP方法通常用来获取资源信息？\", \"difficulty\": \"easy\", \"explanation\": \"根据REST架构风格，在大多数情况下，使用\'GET\'方法来请求访问或检索资源。\", \"correctAnswer\": \"GET\"}]}', '2026-01-07 05:23:02');
