INSERT INTO `generated_questions` VALUES ('2a198ee5-35ac-4d8c-b686-152f6ad78a1f', 'b00060a8-b199-418d-8430-008ac6cb8168', '{\"imageUrl\": null, \"questions\": [{\"id\": \"001\", \"type\": \"__v_isRef\", \"topic\": \"Vue 3响应式系统\", \"options\": [\"__v_observe\", \"__v_raw\", \"__v_isRef\", \"__v_model\"], \"question\": \"以下哪个选项是Vue 3中用来标记响应式引用的内部属性？\", \"difficulty\": \"medium\", \"explanation\": \"在Vue 3的Composition API中，__v_isRef是一个特殊的内部属性，用于标识一个对象是否为ref。\", \"correctAnswer\": \"__v_isRef\"}, {\"id\": \"002\", \"type\": \"__v_isRef\", \"topic\": \"Vue 3响应式系统\", \"options\": [\"_isVue\", \"__ob__\", \"__v_isRef\", \"_data\"], \"question\": \"当使用Vue 3的ref()函数创建一个响应式变量时，该变量将被添加哪种特殊属性以表明它是ref类型？\", \"difficulty\": \"easy\", \"explanation\": \"每个通过ref()创建的对象都会包含__v_isRef属性，这有助于Vue识别并正确处理这些响应式引用。\", \"correctAnswer\": \"__v_isRef\"}, {\"id\": \"003\", \"type\": \"__v_isRef\", \"topic\": \"Vue 3响应式系统\", \"options\": [\"__v_reactive\", \"__v_computed\", \"__v_isRef\", \"__v_watch\"], \"question\": \"如果你需要检查某个值是否是由Vue 3的ref或reactive创建的响应式数据，你应该查找哪个标志？\", \"difficulty\": \"hard\", \"explanation\": \"虽然存在多种方式来创建响应式数据，但__v_isRef是专门用来标识ref类型的标志。\", \"correctAnswer\": \"__v_isRef\"}, {\"id\": \"004\", \"type\": \"__v_isRef\", \"topic\": \"Vue 3响应式系统\", \"options\": [\"__proto__\", \"__defineGetter__\", \"__v_isRef\", \"constructor\"], \"question\": \"在Vue 3中，哪一个属性可以用来区分普通的JavaScript对象和由ref创建的对象？\", \"difficulty\": \"medium\", \"explanation\": \"只有通过ref创建的对象才会拥有__v_isRef属性，这是区分它们与普通JS对象的关键。\", \"correctAnswer\": \"__v_isRef\"}]}', '2026-01-06 22:28:57');
