INSERT INTO `generated_questions` VALUES ('52e84d96-b2e9-4cb9-b110-e9117aa16290', 'b00060a8-b199-418d-8430-008ac6cb8168', '{\"questions\":[{\"id\":\"001\",\"type\":\"__v_isRef\",\"question\":\"以下哪个概念是描述Vue.js中用于优化性能的标志？\",\"options\":[\"__v_isRef\",\"__v_isReactive\",\"__v_isReadonly\",\"__v_isShallow\"],\"correctAnswer\":\"__v_isRef\",\"explanation\":\"__v_isRef是一个内部使用的标志，用来识别一个对象是否被标记为ref，这有助于在框架内部进行性能优化。\",\"difficulty\":\"medium\",\"topic\":\"Vue.js\"},{\"id\":\"002\",\"type\":\"__v_isRef\",\"question\":\"当使用Vue.js时，如何判断一个变量是否通过`ref()`函数创建？\",\"options\":[\"检查是否有`__v_isRef`属性\",\"调用`.value`看是否报错\",\"使用`isRef()`辅助函数\",\"查看变量名前缀\"],\"correctAnswer\":\"使用`isRef()`辅助函数\",\"explanation\":\"虽然可以通过检查`__v_isRef`属性来判断，但推荐的做法是使用Vue提供的`isRef()`函数，这是更安全和规范的方法。\",\"difficulty\":\"easy\",\"topic\":\"Vue.js\"},{\"id\":\"003\",\"type\":\"__v_isRef\",\"question\":\"在Vue 3中，`__v_isRef`主要用于什么？\",\"options\":[\"定义响应式数据\",\"区分普通JS对象与响应式引用\",\"作为组件实例的标识\",\"管理状态树\"],\"correctAnswer\":\"区分普通JS对象与响应式引用\",\"explanation\":\"在Vue 3中，`__v_isRef`是一个特殊的属性，用于帮助框架内部逻辑区分普通的JavaScript对象和由`ref()`创建的响应式引用。\",\"difficulty\":\"medium\",\"topic\":\"Vue.js\"},{\"id\":\"004\",\"type\":\"__v_isRef\",\"question\":\"如果你需要手动创建一个带有`__v_isRef: true`的对象，应该注意什么？\",\"options\":[\"不需要特别注意\",\"确保也实现了.value属性\",\"设置`__v_isRef`后不能再改变\",\"只能通过特定API修改\"],\"correctAnswer\":\"确保也实现了.value属性\",\"explanation\":\"创建自定义的带有`__v_isRef`属性的对象时，重要的是它还需要实现`.value`属性以符合Vue对于ref的要求，否则可能无法正确地工作于Vue的响应系统中。\",\"difficulty\":\"hard\",\"topic\":\"Vue.js\"}],\"imageUrl\":null}', '2026-01-12 09:13:53');
INSERT INTO `generated_questions` VALUES ('54430cc6-46b5-46d8-8db5-0618e41d0a95', 'test-kb-123', '{\"id\": \"Q101\", \"type\": \"multipleChoice\", \"topic\": \"牛顿运动定律\", \"options\": [\"作用力和反作用力总是大小相等、方向相反\", \"作用力与反作用力作用于同一物体上\", \"如果一个物体对另一个物体施加了力，则另一个物体会以同样大小但方向相反的力回施\", \"作用力和反作用力可以不同性质\"], \"imageUrl\": null, \"question\": \"下列关于牛顿第三定律的描述哪些是正确的？\", \"difficulty\": \"medium\", \"explanation\": \"根据牛顿第三定律，两个物体之间的相互作用力总是成对出现的，并且这两个力大小相等、方向相反。但是，这对力分别作用在不同的物体上，而不是同一个物体上。此外，作用力和反作用力必须是同种性质的力。\", \"correctAnswer\": [\"作用力和反作用力总是大小相等、方向相反\", \"如果一个物体对另一个物体施加了力，则另一个物体会以同样大小但方向相反的力回施\"]}', '2026-01-05 22:50:52');
