INSERT INTO `generated_questions` VALUES ('8973eced-0cc0-4696-b69a-ad465c525e0f', '77f93075-8d32-4032-84cc-bd923e9725f1', '{\"imageUrl\": null, \"questions\": [{\"id\": \"001\", \"type\": \"__v_isRef\", \"topic\": \"Vue3响应式系统\", \"options\": [\"__v_raw\", \"__v_isRef\", \"__ob__\", \"__proto__\"], \"question\": \"下列哪个选项是Vue3中用于标记响应式引用的属性？\", \"difficulty\": \"medium\", \"explanation\": \"在Vue3中，使用`__v_isRef`作为内部属性来标记一个对象是否为响应式引用。\", \"correctAnswer\": \"__v_isRef\"}, {\"id\": \"002\", \"type\": \"__v_isRef\", \"topic\": \"Vue3响应式API\", \"options\": [\"__v_isReactive\", \"__v_isRef\", \"isRef\", \"ref\"], \"question\": \"当创建一个ref时，Vue会自动添加哪个属性以标识其为响应式引用？\", \"difficulty\": \"easy\", \"explanation\": \"`__v_isRef`属性由Vue框架自动附加到每个通过ref()函数创建的对象上，用以指示该对象是一个响应式引用。\", \"correctAnswer\": \"__v_isRef\"}, {\"id\": \"003\", \"type\": \"__v_isRef\", \"topic\": \"Vue3响应式数据检测\", \"options\": [\"_isVue\", \"__v_isRef\", \"isProxy\", \"isReactive\"], \"question\": \"如果想要检查某个值是否被Vue认为是ref，应该查看它是否有哪个特定属性？\", \"difficulty\": \"medium\", \"explanation\": \"为了确定一个值是否是由ref创建的响应式引用，可以检查它是否具有`__v_isRef`属性。\", \"correctAnswer\": \"__v_isRef\"}]}', '2026-01-06 21:33:51');
