INSERT INTO `generated_questions` VALUES ('925d4217-05e0-43ca-930d-22566d1c0168', '7d3dc77e-95e3-4d75-8185-1ada435d66a3', '{\"imageUrl\": null, \"questions\": [{\"id\": \"q1\", \"type\": \"__v_isRef\", \"topic\": \"Vue.js响应式系统\", \"options\": [\"__v_isRef\", \"__ob__\", \"__proto__\", \"data\"], \"question\": \"以下哪项不是Vue.js中的响应式属性标识？\", \"difficulty\": \"medium\", \"explanation\": \"在Vue.js中，__v_isRef用于标记一个对象是否为ref类型，而__ob__是观察者对象的引用，__proto__则是原型链的一部分。\'data\'是一个普通选项，并非用来直接标识响应式的。\", \"correctAnswer\": \"data\"}, {\"id\": \"q2\", \"type\": \"__v_isRef\", \"topic\": \"Vue3响应式API\", \"options\": [\"__v_isReactive\", \"__v_isRef\", \"isRef\", \"reactive\"], \"question\": \"在Vue3中，使用哪个特殊属性来检查一个对象是否通过ref创建？\", \"difficulty\": \"easy\", \"explanation\": \"Vue3引入了__v_isRef作为内部标志，以快速判断给定值是否由ref函数创建。\", \"correctAnswer\": \"__v_isRef\"}, {\"id\": \"q3\", \"type\": \"__v_isRef\", \"topic\": \"Vue工具函数\", \"options\": [\"useRefCheck\", \"isRef\", \"refCheck\", \"checkIsRef\"], \"question\": \"下面哪个方法可以用来确定一个变量是否是由Vue的ref函数产生的？\", \"difficulty\": \"medium\", \"explanation\": \"Vue提供了一个辅助函数isRef，它可以用来检测一个值是否被ref包装过。\", \"correctAnswer\": \"isRef\"}, {\"id\": \"q4\", \"type\": \"__v_isRef\", \"topic\": \"Vue.js ref机制\", \"options\": [\"原始值\", \"一个代理对象\", \"undefined\", \"null\"], \"question\": \"当尝试访问一个ref对象时，实际访问的是什么？\", \"difficulty\": \"hard\", \"explanation\": \"通过ref创建的对象，在访问其.value属性时会返回存储的原始数据。\", \"correctAnswer\": \"原始值\"}, {\"id\": \"q5\", \"type\": \"__v_isRef\", \"topic\": \"Vue.js状态管理\", \"options\": [\"直接赋值\", \"使用set方法\", \".value = 新值\", \"调用update方法\"], \"question\": \"如果想改变一个用ref定义的变量的值，应该怎么做？\", \"difficulty\": \"easy\", \"explanation\": \"对于ref类型的变量，可以通过修改其.value属性来更新值。\", \"correctAnswer\": \".value = 新值\"}, {\"id\": \"q6\", \"type\": \"__v_isRef\", \"topic\": \"Vue3响应式API\", \"options\": [\"使用ref\", \"使用reactive\", \"两者都可以\", \"无需特别设置\"], \"question\": \"在Vue3中，如何确保一个对象是响应式的并且可以被追踪？\", \"difficulty\": \"medium\", \"explanation\": \"ref和reactive都是Vue3提供的创建响应式数据的方式，适用于不同场景。\", \"correctAnswer\": \"两者都可以\"}, {\"id\": \"q7\", \"type\": \"__v_isRef\", \"topic\": \"Vue3高级特性\", \"options\": [\"只能用于基本类型\", \"可以用于复杂对象\", \"不支持嵌套结构\", \"不能与reactive一起使用\"], \"question\": \"关于Vue3中的ref，下列说法正确的是？\", \"difficulty\": \"hard\", \"explanation\": \"ref不仅可以包裹基础类型的数据，也可以用于数组或对象等复杂结构。\", \"correctAnswer\": \"可以用于复杂对象\"}, {\"id\": \"q8\", \"type\": \"__v_isRef\", \"topic\": \"Vue3实用工具\", \"options\": [\"将reactive对象转换成多个ref对象\", \"仅用于监听变化\", \"替换所有ref实例\", \"转换props\"], \"question\": \"Vue3中的toRefs函数主要用于什么？\", \"difficulty\": \"medium\", \"explanation\": \"toRefs允许我们将reactive对象内的每个属性都转换成独立的ref对象，便于解构。\", \"correctAnswer\": \"将reactive对象转换成多个ref对象\"}, {\"id\": \"q9\", \"type\": \"__v_isRef\", \"topic\": \"Vue3组件开发\", \"options\": [\"const count = ref(0);\", \"let count = 0;\", \"const count = reactive(0);\", \"var count = new Ref(0);\"], \"question\": \"在Vue组件内，如何正确地初始化一个可变的状态变量？\", \"difficulty\": \"easy\", \"explanation\": \"推荐使用ref来定义组件内的状态变量，它提供了更灵活的响应式能力。\", \"correctAnswer\": \"const count = ref(0);\"}, {\"id\": \"q10\", \"type\": \"__v_isRef\", \"topic\": \"Vue3模板语法\", \"options\": [\"<div ref=\'myDiv\'></div>\", \"<div :ref=\'myDiv\'></div>\", \"<div v-bind:ref=\'myDiv\'></div>\", \"<div @ref=\'myDiv\'></div>\"], \"question\": \"下面哪个选项展示了正确使用ref获取DOM元素的方法？\", \"difficulty\": \"medium\", \"explanation\": \"在模板中，直接使用ref属性绑定一个字符串或回调函数即可实现对DOM元素的引用。\", \"correctAnswer\": \"<div ref=\'myDiv\'></div>\"}, {\"id\": \"q11\", \"type\": \"__v_isRef\", \"topic\": \"Vue3组合式API\", \"options\": [\"const count = { value: 0 };\", \"const count = ref(0);\", \"let count = 0; const count = ref(count);\", \"const [count, setCount] = useState(0);\"], \"question\": \"在组合式API中，如何同时声明并初始化一个响应式变量及其初始值？\", \"difficulty\": \"easy\", \"explanation\": \"使用ref()函数可以直接创建一个带有初始值的响应式引用。\", \"correctAnswer\": \"const count = ref(0);\"}, {\"id\": \"q12\", \"type\": \"__v_isRef\", \"topic\": \"Vue3组件间通信\", \"options\": [\"通过props传递\", \"直接在子组件中定义相同的ref\", \"使用provide/inject\", \"无法跨组件共享ref\"], \"question\": \"如果有一个ref对象需要在另一个组件中使用，你应该怎么做？\", \"difficulty\": \"hard\", \"explanation\": \"利用provide/inject机制可以在父组件向任意层级的子组件传递ref或其他数据。\", \"correctAnswer\": \"使用provide/inject\"}]}', '2026-01-10 00:08:58');
INSERT INTO `generated_questions` VALUES ('98a15bbb-fc70-4ef5-8699-22c8bacf97bc', 'test-kb-123', '{\"id\": \"Q102\", \"type\": \"multipleChoice\", \"topic\": \"能量守恒\", \"options\": [\"动能转化为势能\", \"势能转化为动能\", \"总机械能保持不变（假设没有空气阻力）\", \"重力势能随着高度增加而减少\"], \"imageUrl\": null, \"question\": \"当一个物体自由下落时，下面哪个或哪几个选项正确描述了它的能量转换过程？\", \"difficulty\": \"medium\", \"explanation\": \"当物体自由下落时，其位置相对于地面降低，因此它失去重力势能；同时，由于速度加快，所以获得了动能。如果没有外部做功（如空气阻力），那么系统的总机械能（即动能加上势能）将保持守恒。因此，在理想情况下，减少的重力势能完全转化为了增加的动能。\", \"correctAnswer\": [\"势能转化为动能\", \"总机械能保持不变（假设没有空气阻力）\"]}', '2026-01-05 22:50:52');
