INSERT INTO `prompt_templates` VALUES ('prompt_1765650417768_x4e0yj8y4', '陈皮', '销售', 'customer_service', '[]', 'gpt', '你是一个专业的陈皮销售专家。你的任务是热卖。\n\n请根据以下要求提供帮助：{{user_input}}\n\n优化', '你是一个专业的陈皮销售专家。你的任务是热卖。', '请根据以下要求提供帮助：{{user_input}}', '优化', 0.70, 2048, 1.00, 0.00, 0.00, '[]', '{\"score\": 82, \"rating\": \"优秀\", \"dimensions\": {\"专业性\": 85, \"具体性\": 65, \"完整性\": 70, \"清晰度\": 78, \"可执行性\": 70}, \"evaluatedAt\": \"2025-12-13T18:23:12.963Z\", \"suggestions\": [\"明确目标市场\", \"列出输出格式\", \"增加产品信息与USP\", \"加入合规与伦理边界\", \"规定风格与语气\"], \"detailedFeedback\": {\"专业性\": \"风格与表述专业，但需纳入营销合规与伦理边界，提升在商业场景中的可信度与可持续性。\", \"具体性\": \"缺少关键要素，如目标受众、产品特性、价格区间、促销策略、需要产出哪些具体文案或资料，导致执行细节不足。\", \"完整性\": \"应补充产品信息（来源、等级、功效、适用场景）、竞争分析、市场定位、评估标准等，以形成完整的操作指引。\", \"清晰度\": \"当前提示明确要成为‘专业的陈皮销售专家’，但对目标、输出类型及成功标准缺乏清晰界定，容易导致目标偏离。\", \"可执行性\": \"具备执行潜力，但应给出明确的交付物清单（如产品描述、卖点列表、广告文案模板、问答集等）以及约束条件。\"}}', 0, 0.00, 0, 'admin', '2025-12-14 02:26:57', '2025-12-14 02:26:57');
INSERT INTO `prompt_templates` VALUES ('prompt_1765651035948_6kmrwnjh2', '9', '9', 'customer_service', '[]', 'gpt', '你是一个专业的陈皮专家专家。你的任务是卖陈皮。\n\n请根据以下要求提供帮助：{{user_input}}', '你是一个专业的陈皮专家专家。你的任务是卖陈皮。', '请根据以下要求提供帮助：{{user_input}}', NULL, 0.70, 2048, 1.00, 0.00, 0.00, '[]', '{\"score\": 70, \"rating\": \"良好\", \"dimensions\": {\"专业性\": 70, \"具体性\": 70, \"完整性\": 70, \"清晰度\": 70, \"可执行性\": 70}, \"evaluatedAt\": \"2025-12-13T18:37:07.892Z\", \"suggestions\": [\"AI评估暂时不可用，请手动检查提示词\"], \"detailedFeedback\": {\"专业性\": \"无法解析AI评估结果\", \"具体性\": \"无法解析AI评估结果\", \"完整性\": \"无法解析AI评估结果\", \"清晰度\": \"无法解析AI评估结果\", \"可执行性\": \"无法解析AI评估结果\"}}', 0, 0.00, 0, 'admin', '2025-12-14 02:37:16', '2025-12-14 02:37:16');
