INSERT INTO `training_games` VALUES ('0d2273bb-7441-4b4c-ab72-fbe61704193b', 'default', '{\"gameCode\":null,\"gameConfig\":{\"levelCount\":5,\"questionsPerLevel\":10,\"difficulty\":\"medium\",\"physics\":{\"gravity\":0.5,\"friction\":0.1,\"restitution\":0.8}},\"assets\":[],\"questions\":[{\"error\":\"提供的知识库信息不完整，缺少关键概念和难度级别等重要信息，请提供完整的信息以便生成题目。\",\"imageUrl\":null},{\"questions\":[{\"id\":\"001\",\"type\":\"__v_isRef\",\"question\":\"以下哪个概念是描述Vue.js中用于优化性能的标志？\",\"options\":[\"__v_isRef\",\"__v_isReactive\",\"__v_isReadonly\",\"__v_isShallow\"],\"correctAnswer\":\"__v_isRef\",\"explanation\":\"__v_isRef是一个内部使用的标志，用来识别一个对象是否被标记为ref，这有助于在框架内部进行性能优化。\",\"difficulty\":\"medium\",\"topic\":\"Vue.js\"},{\"id\":\"002\",\"type\":\"__v_isRef\",\"question\":\"当使用Vue.js时，如何判断一个变量是否通过`ref()`函数创建？\",\"options\":[\"检查是否有`__v_isRef`属性\",\"调用`.value`看是否报错\",\"使用`isRef()`辅助函数\",\"查看变量名前缀\"],\"correctAnswer\":\"使用`isRef()`辅助函数\",\"explanation\":\"虽然可以通过检查`__v_isRef`属性来判断，但推荐的做法是使用Vue提供的`isRef()`函数，这是更安全和规范的方法。\",\"difficulty\":\"easy\",\"topic\":\"Vue.js\"},{\"id\":\"003\",\"type\":\"__v_isRef\",\"question\":\"在Vue 3中，`__v_isRef`主要用于什么？\",\"options\":[\"定义响应式数据\",\"区分普通JS对象与响应式引用\",\"作为组件实例的标识\",\"管理状态树\"],\"correctAnswer\":\"区分普通JS对象与响应式引用\",\"explanation\":\"在Vue 3中，`__v_isRef`是一个特殊的属性，用于帮助框架内部逻辑区分普通的JavaScript对象和由`ref()`创建的响应式引用。\",\"difficulty\":\"medium\",\"topic\":\"Vue.js\"},{\"id\":\"004\",\"type\":\"__v_isRef\",\"question\":\"如果你需要手动创建一个带有`__v_isRef: true`的对象，应该注意什么？\",\"options\":[\"不需要特别注意\",\"确保也实现了.value属性\",\"设置`__v_isRef`后不能再改变\",\"只能通过特定API修改\"],\"correctAnswer\":\"确保也实现了.value属性\",\"explanation\":\"创建自定义的带有`__v_isRef`属性的对象时，重要的是它还需要实现`.value`属性以符合Vue对于ref的要求，否则可能无法正确地工作于Vue的响应系统中。\",\"difficulty\":\"hard\",\"topic\":\"Vue.js\"}],\"imageUrl\":null},{\"message\":\"请提供具体的知识库主题、关键概念以及难度级别信息，以便于生成符合要求的题目。\",\"imageUrl\":null},{\"message\":\"请提供具体的知识库主题、关键概念及难度级别，以便生成符合要求的题目。\",\"imageUrl\":null}]}', '/games/physics-game-1768180441079.html', '2026-01-12 09:14:01');
