INSERT INTO `trend_analysis_history` VALUES (1, NULL, 'analysis', '', 'Content Analysis for Social Media Post', 'https://www.xiaohongshu.com/explore/69427ac7000000000d037a1d?app_platform=android&ignoreEngage=true&app_version=9.13.1&share_from_user_hidden=true&xsec_source=app_share&type=normal&xsec_token=CB0vnQJ2z5fA73Ae5ZCB8CNcrLgnwECkNGjn9n_DLv0mw=&author_share=1&shareRedId=Nzw4NEk2SUA-OTwzQUsyOTY6PkxFNTw9&apptime=1766299742&share_id=a56a71396cf346618dbfd15d497387ac&share_channel=copy_link&appuid=5664f1e782718c23075ea064&xhsshare=CopyLink', 'social media, content analysis, fallback, data unavailable', 'article', 'Pure Content', '[\"#SocialMedia\",\"#ContentAnalysis\",\"#Fallback\"]', 0, 'The provided link leads to a post on Xiaohongshu, but the content scraping failed. Based on the context, this analysis is a fallback and assumes a general type of content without specific details.', '{\"tags\": [\"#SocialMedia\", \"#ContentAnalysis\", \"#Fallback\"], \"type\": \"article\", \"cover\": \"social media, content analysis, fallback, data unavailable\", \"score\": 0, \"title\": \"Content Analysis for Social Media Post\", \"images\": [], \"isSoft\": false, \"reason\": \"Since the actual content could not be scraped, it\'s impossible to determine if it\'s an advertisement or viral content. The default classification in such cases leans towards \'Pure Content\' as no marketing or high engagement indicators are present.\", \"content\": \"Content scraping failed. This is a fallback analysis.\", \"summary\": \"The provided link leads to a post on Xiaohongshu, but the content scraping failed. Based on the context, this analysis is a fallback and assumes a general type of content without specific details.\", \"mediaUrl\": \"\"}', '2025-12-21 21:17:33');
