-- ----------------------------
-- Table structure for llm_configs
-- ----------------------------
DROP TABLE IF EXISTS `llm_configs`;
CREATE TABLE `llm_configs`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int NULL DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` enum('openai','baidu','milives','custom','hunyuan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'chat' COMMENT '模型类型: chat, embedding, rerank (支持逗号分隔多个)',
  `api_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `base_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `temperature` decimal(3, 2) NULL DEFAULT 0.70,
  `max_tokens` int NULL DEFAULT 2048,
  `reasoning_effort` enum('minimal','low','medium','high') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'medium' COMMENT '推理努力程度/思考长度',
  `top_p` decimal(3, 2) NULL DEFAULT 1.00,
  `frequency_penalty` decimal(3, 2) NULL DEFAULT 0.00,
  `presence_penalty` decimal(3, 2) NULL DEFAULT 0.00,
  `system_prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `user_prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '用户提示词',
  `recall_rate` decimal(3, 2) NULL DEFAULT 0.80 COMMENT '召回率 (0.0 - 1.0)',
  `hallucination_rate` decimal(3, 2) NULL DEFAULT 0.10 COMMENT '幻觉度 (0.0 - 1.0)',
  `mcp_tools` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT 'MCP 工具配置，JSON 格式',
  `is_default` tinyint(1) NULL DEFAULT 0,
  `enable_ip_check` tinyint(1) NULL DEFAULT 0 COMMENT 'IP地址监测功能开关',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `output_style` enum('non-streaming','streaming','streamable') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'streaming',
  `embedding_dimensions` int NULL DEFAULT NULL COMMENT '嵌入模型向量维度',
  `batch_size` int NULL DEFAULT NULL COMMENT '嵌入模型批处理大小',
  `top_k` int NULL DEFAULT NULL COMMENT '重排序模型 Top K 结果',
  `score_threshold` decimal(3, 2) NULL DEFAULT NULL COMMENT '重排序模型置信度阈值',
  `vector_db_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '向量数据库类型',
  `vector_db_endpoint` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '向量数据库端点',
  `seed` int NULL DEFAULT NULL,
  `stream` tinyint(1) NULL DEFAULT 1,
  `endpoint_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `endpoint_alias` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `endpoint_model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `timeout_ms` int NULL DEFAULT 60000,
  `rate_limit_rpm` int NULL DEFAULT NULL,
  `rate_limit_concurrency` int NULL DEFAULT NULL,
  `enable_kb_search` tinyint(1) NULL DEFAULT 0,
  `enable_web_search` tinyint(1) NULL DEFAULT 0,
  `thinking_depth_level` int NULL DEFAULT 3,
  `cot_enabled` tinyint(1) NULL DEFAULT 0,
  `cot_granularity` int NULL DEFAULT 3,
  `cot_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  CONSTRAINT `llm_configs_chk_1` CHECK (json_valid(`mcp_tools`)),
  CONSTRAINT `llm_configs_chk_2` CHECK (json_valid(`cot_config`))
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

