-- ----------------------------
-- Table structure for llm_conversation_logs
-- ----------------------------
DROP TABLE IF EXISTS `llm_conversation_logs`;
CREATE TABLE `llm_conversation_logs`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `conversation_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `model` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'LLM模型名称',
  `prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户输入',
  `thinking_process` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '模型思考过程',
  `response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型回答结果',
  `token_usage` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT 'Token使用统计',
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '元数据（如时间戳、IP地址等）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_conversation_id`(`conversation_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'LLM对话日志表' ROW_FORMAT = DYNAMIC;

