-- ----------------------------
-- Table structure for mcp_configs
-- ----------------------------
DROP TABLE IF EXISTS `mcp_configs`;
CREATE TABLE `mcp_configs`  (
  `id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MCP服务器名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '描述',
  `server_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务器URL或包名',
  `server_type` enum('uvx','npm','pip','docker','mcp.so','custom') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务器类型',
  `config_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '配置数据',
  `auto_install` tinyint(1) NULL DEFAULT 0 COMMENT '是否自动安装',
  `is_enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `install_status` enum('manual','pending','installing','installed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'manual' COMMENT '安装状态',
  `install_output` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '安装输出',
  `install_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '安装错误信息',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_server_type`(`server_type` ASC) USING BTREE,
  INDEX `idx_is_enabled`(`is_enabled` ASC) USING BTREE,
  INDEX `idx_install_status`(`install_status` ASC) USING BTREE,
  CONSTRAINT `mcp_configs_chk_1` CHECK (json_valid(`config_data`))
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'MCP配置表' ROW_FORMAT = DYNAMIC;

