  `timezone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'Asia/Shanghai',
  `notifications_enabled` tinyint(1) NULL DEFAULT 1,
  `auto_save` tinyint(1) NULL DEFAULT 1,
