-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '用户ID，自增主键',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户名，唯一',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号，唯一',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱，唯一',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码（SHA256加密）',
  `password_hash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '密码哈希值（兼容字段）',
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '昵称',
  `nickname_updated_at` timestamp NULL DEFAULT NULL COMMENT '昵称最后修改时间',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像URL',
  `bio` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '个人简介',
  `gender` enum('male','female','other','unknown') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'unknown' COMMENT '性别',
  `birthday` date NULL DEFAULT NULL COMMENT '生日',
  `status` enum('active','inactive','banned') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'active' COMMENT '用户状态',
  `balance` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '账户余额',
  `account_balance` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '账户余额(RMB)',
  `debt_amount` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '欠费金额',
  `debt_status` enum('none','pending','overdue','frozen') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'none' COMMENT '欠费状态：none(无欠费), pending(待支付), overdue(逾期), frozen(已冻结)',
  `debt_updated_at` timestamp NULL DEFAULT NULL COMMENT '欠费信息最后更新时间',
  `token_total` bigint NULL DEFAULT 1000000 COMMENT '总token数量',
  `token_used` bigint NULL DEFAULT 0 COMMENT '已使用token数量',
  `activated_models` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '用户激活的模型ID列表，JSON格式存储数组',
  `apikey` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联的 LLM 配置 ID，用于从 RustFS 实时获取 API Key',
  `points` int NULL DEFAULT 0 COMMENT '积分',
  `level` int NULL DEFAULT 1 COMMENT '用户等级',
  `email_verified` tinyint(1) NULL DEFAULT 0 COMMENT '邮箱是否已验证',
  `phone_verified` tinyint(1) NULL DEFAULT 0 COMMENT '手机号是否已验证',
  `wechat_openid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '微信OpenID，唯一',
  `alipay_user_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支付宝用户ID，唯一',
  `register_ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '注册IP地址',
  `last_login_at` timestamp NULL DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最后登录IP地址',
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '删除时间（软删除）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ban_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '封禁类型: temporary(临时) 或 permanent(永久)',
  `ban_days` int NULL DEFAULT NULL COMMENT '临时封禁天数',
  `ban_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '封禁理由',
  `ban_until` timestamp NULL DEFAULT NULL COMMENT '封禁解除时间',
  `banned_by` int NULL DEFAULT NULL COMMENT '封禁操作者ID',
  `banned_at` timestamp NULL DEFAULT NULL COMMENT '封禁时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `username`(`username` ASC) USING BTREE,
  UNIQUE INDEX `phone`(`phone` ASC) USING BTREE,
  UNIQUE INDEX `email`(`email` ASC) USING BTREE,
  UNIQUE INDEX `wechat_openid`(`wechat_openid` ASC) USING BTREE,
  UNIQUE INDEX `alipay_user_id`(`alipay_user_id` ASC) USING BTREE,
  INDEX `idx_users_username`(`username` ASC) USING BTREE,
  INDEX `idx_users_phone`(`phone` ASC) USING BTREE,
  INDEX `idx_users_email`(`email` ASC) USING BTREE,
  INDEX `idx_users_status`(`status` ASC) USING BTREE,
  INDEX `idx_users_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_users_deleted_at`(`deleted_at` ASC) USING BTREE,
  INDEX `idx_ban_until`(`ban_until` ASC) USING BTREE,
  INDEX `idx_debt_status`(`debt_status` ASC) USING BTREE,
  INDEX `idx_debt_amount`(`debt_amount` ASC) USING BTREE,
  CONSTRAINT `users_chk_1` CHECK (json_valid(`activated_models`))
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of users
-- ----------------------------

