  CONSTRAINT `writing_agent_knowledge_bases_ibfk_1` FOREIGN KEY (`writing_agent_id`) REFERENCES `writing_agents` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `writing_agent_knowledge_bases_ibfk_2` FOREIGN KEY (`knowledge_base_id`) REFERENCES `knowledge_bases` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '写作智能体与知识库关联表' ROW_FORMAT = DYNAMIC;

